## Bevy version

Bevy 0.5

## Reproduction

```rust
fn is_resource_scope_unsound() {
    let mut world = World::new();
    world.insert_resource(0u32);
    world.resource_scope(|world, res: Mut<u32>| {
        println!("{}", &*res);
        world.insert_resource(10u32);
        world.remove_resource::<u32>();
        println!("{}", &*res);
    });
}
```

